VALUES (11158, 'tt0104437', NULL, 'Honey, I Blew Up the Kid', 'Honey, I Blew Up the Kid', 'movie', 1992, 'https://image.tmdb.org/t/p/w500/4EGqDo2pP2ZL0TCcYDGnwsU8liQ.jpg', 'https://image.tmdb.org/t/p/original/r4Vx7kne6dovybAJR4LsR4eQCxP.jpg', 'Wayne Szalinski is at it again. But instead of shrinking things, he tries to make a machine that can make things grow. As in the first one, his machine isn''t quite accurate. But when he brings Nick & his toddler son Adam to see his invention, the machine unexpectedly starts working. And when Adam comes right up to the machine, he gets zapped along with his stuffed bunny.', NULL, NULL, 7.3679, 5.296, 0, 6.04, '2026-10-24 22:41:42', '2026-10-24 22:41:42')
