VALUES (499726, 'tt7205316', NULL, 'MILF', 'MILF', 'movie', 2018, 'https://image.tmdb.org/t/p/w500/qBU82NPKF1LOAD9D3jLUqypyEdL.jpg', 'https://image.tmdb.org/t/p/original/mwyO0J1pwaqqKygU0gnIyRP1cFN.jpg', 'Three childhood friends - Elise, Sonia and Cecile - leave for a summer in the South of France to help clear Cecile’s holiday house before it is put up for sale. There, they soon become the prime targets of three horny young men, for whom these single forty-year-old women are much more attractive than girls their age.', NULL, NULL, 4.278, 5.682, 0, 8.51, '2026-10-24 22:41:42', '2026-10-24 22:41:42')
