VALUES (1252377, 'tt31519456', NULL, 'La Dolce Villa', 'La Dolce Villa', 'movie', 2025, 'https://image.tmdb.org/t/p/w500/sEma5RN8aZ5Yu2Dkefyn5ULdlc1.jpg', 'https://image.tmdb.org/t/p/original/s1ge9SG2zfJdMeZ69VMEbxeKuAE.jpg', 'When his daughter decides to buy a crumbling Tuscan villa, Eric rushes to Italy to talk her out of it — and instead finds beauty, romance and new purpose.', NULL, NULL, 3.4677, 6.342, 0, 9.01, '2026-10-24 22:41:42', '2026-10-24 22:41:42')
