VALUES (8967, 'tt0478304', NULL, 'The Tree of Life', 'The Tree of Life', 'movie', 2011, 'https://image.tmdb.org/t/p/w500/l8cwuB5WJSoj4uMAsnzuHBOMaSJ.jpg', 'https://image.tmdb.org/t/p/original/xq1HIwZq9VbuvMQELAua1nqEkH.jpg', 'The impressionistic story of a Texas family in the 1950s. The film follows the life journey of the eldest son, Jack, through the innocence of childhood to his disillusioned adult years as he tries to reconcile a complicated relationship with his father. Jack finds himself a lost soul in the modern world, seeking answers to the origins and meaning of life while questioning the existence of faith.', NULL, NULL, 5.1362, 6.719, 0, 5.10567391304347779e+01, '2026-07-15 12:01:52', '2026-10-24 22:41:42')
