VALUES (588, 'tt0384537', NULL, 'Silent Hill', 'Silent Hill', 'movie', 2006, 'https://image.tmdb.org/t/p/w500/r0bEDWO2w4a43K2xTNSF284qOsc.jpg', 'https://image.tmdb.org/t/p/original/48TM0HjZSRjIr4QMuDTsMWcz7gX.jpg', 'Rose, a desperate mother, takes her adopted daughter, Sharon, to the town of Silent Hill in an attempt to cure her of her ailment. After a violent car crash, Sharon disappears, and Rose embarks on a horrific journey to get her back and begins to uncover the truth behind the apocalyptic disaster that burned the town 30 years earlier.', NULL, NULL, 10.8422, 6.645, 0, 5.28658333333333345e+01, '2026-07-15 12:01:52', '2026-10-24 22:41:42')
