VALUES (41428, 'tt0096251', NULL, 'Tetsuo: The Iron Man', '鉄男', 'movie', 1989, 'https://image.tmdb.org/t/p/w500/lARc59hUAKW3ziWddftUnZ99R8c.jpg', 'https://image.tmdb.org/t/p/original/xt75NSIlfzwPwuBsuarB3i1mBxj.jpg', 'A "metal fetishist", driven mad by the maggots wriggling in the wound he''s made to embed metal into his flesh, runs out into the night and is accidentally run down by a Japanese businessman and his girlfriend. The pair dispose of the corpse in hopes of quietly moving on with their lives. However, the businessman soon finds that he is now plagued by a vicious curse that transforms his flesh into iron.', NULL, NULL, 4.2205, 6.959, 0, 6.74565573770491795e+01, '2026-07-15 12:01:52', '2026-10-24 22:41:42')
