VALUES (4977, 'tt0851578', NULL, 'Paprika', 'パプリカ', 'movie', 2006, 'https://image.tmdb.org/t/p/w500/bLUUr474Go1DfeN1HLjE3rnZXBq.jpg', 'https://image.tmdb.org/t/p/original/6oXn0037WWw4fTCc3Qczof71lSp.jpg', 'Dr. Atsuko Chiba is a research psychologist who uses a device called the DC Mini to enter her patients'' dreams, wherein she adopts the alter-ego "Paprika". When the device is stolen, she must stop rogue elements from merging the dream and waking worlds.', NULL, NULL, 8.103, 7.814, 0, 7.48011428571428496e+01, '2026-07-15 12:01:52', '2026-10-24 22:41:42')
