VALUES (636, 'tt0066434', NULL, 'THX 1138', 'THX 1138', 'movie', 1971, 'https://image.tmdb.org/t/p/w500/pPyEXW7h2SJRjTsHZqrIlXxOgW9.jpg', 'https://image.tmdb.org/t/p/original/fM9ODwfR7m8fI2g99M9WyhvqXtI.jpg', 'People in the future live in a totalitarian society. A technician named THX 1138 lives a mundane life between work and taking a controlled consumption of drugs that the government uses to make puppets out of people. As THX is without drugs for the first time he has feelings for a woman and they start a secret relationship.', NULL, NULL, 3.8045, 6.433, 0, 2.2554117647058824e+01, '2026-07-15 12:01:52', '2026-10-24 22:41:42')
