VALUES (637, 'tt0118799', NULL, 'Life Is Beautiful', 'La vita è bella', 'movie', 1997, 'https://image.tmdb.org/t/p/w500/74hLDKjD5aGYOotO6esUVaeISa2.jpg', 'https://image.tmdb.org/t/p/original/6aNKD81RHR1DqUUa8kOZ1TBY1Lp.jpg', 'A touching story of an Italian book seller of Jewish ancestry who lives in his own little fairy tale. His creative and happy life would come to an abrupt halt when his entire family is deported to a concentration camp during World War II. While locked up he tries to convince his son that the whole thing is just a game.', NULL, NULL, 18.032, 8.439, 0, 17.5325, '2026-07-20 04:02:06', '2026-10-24 22:41:42')
