VALUES (121072, 'tt2215676', NULL, 'The Warped Forest', 'あさっての森', 'movie', 2011, 'https://image.tmdb.org/t/p/w500/52QqDmcX96S4VysCTdGhPe5P90E.jpg', 'https://image.tmdb.org/t/p/original/sPbqfEx2L15wq1hmdhYngUIabUY.jpg', 'Settle into your chair and be transported to a place both familiar and alien; where a giant shop-girl can barely fit in her store, there''s a weird green pod in every bedroom, and terrifying wood nymphs provide a heartbroken woman with the anatomically correct fruit everyone seems to covet. In the end we are left, like Alice, with the Red King''s conundrum: are we dreaming them or are they dreaming us?', NULL, NULL, 1.1168, 5.2, 0, 1.19099999999999983e+01, '2026-08-11 02:46:38', '2026-10-24 22:41:42')
