VALUES (10867, 'tt0213847', NULL, 'Malena', 'Malèna', 'movie', 2000, 'https://image.tmdb.org/t/p/w500/3OyQTl0IGkbnjDxd3MhztfPE34g.jpg', 'https://image.tmdb.org/t/p/original/vadUKKQixxOKWkcuZ1SUEoBQeVG.jpg', '12-year-old Renato experiences three significant events on the same day: the beginning of the Second World War, getting a bike, and witnessing the arrival of the gorgeous Malèna. Through his eyes, we see the curse of beauty and loneliness of Malena, whose husband is presumed dead, and, through his soul, we see his love for her.', NULL, NULL, 26.1606, 7.547, 0, 11.27, '2026-08-12 02:31:31', '2026-10-24 22:41:42')
